/* Links between the original, user-edited calculators and added tools. */
(function(){const en=document.documentElement.lang==='en',T=(a,b)=>en?b:a,kind=document.body.dataset.handoff,query=new URLSearchParams(location.search),main=document.querySelector('main'),section=document.createElement('section');section.className='transfer-actions';section.innerHTML='<h2>'+T('Tiếp tục tính toán','Continue calculations')+'</h2><p>'+T('Chuyển kết quả hiện tại sang công cụ tiếp theo; kiểm tra các thông số còn lại tại trang đích.','Pass current results to the next tool; review the remaining inputs on the destination page.')+'</p><div class="calc-links"></div>';main.insertBefore(section,main.querySelector('.calculator-disclaimer')||main.querySelector('.useful-links'));const target=section.querySelector('.calc-links');
function a(slugs,params,label){return'<a class="calc-link" href="/'+(en?'en':'vi')+'/'+slugs[en?1:0]+'/?'+new URLSearchParams(params)+'">'+label+' →</a>';}
if(kind==='duct'&&query.has('flow')){const q=Number(query.get('flow'));if(Number.isFinite(q)&&q>0&&q<=1e7){document.getElementById('unit').value='3600';priorUnit=3600;document.getElementById('flow').value=q;update();}}
if(kind==='water'&&query.has('flow')){const q=Number(query.get('flow'));if(Number.isFinite(q)&&q>0&&q<=1e7){W('unit').value='3600';waterUnit=3600;W('flow').value=q;if(['chiller','supply'].includes(query.get('system')))W('system').value=query.get('system');waterSystem();}}
function refresh(){target.innerHTML='';if(kind==='heat'){if(typeof lastCoolingResult!=='undefined'&&lastCoolingResult&&lastCoolingResult.r.design>0){const r=lastCoolingResult.r;target.innerHTML=a(['quy-doi-luu-luong','load-to-flow'],{load:r.design/1000,unit:'kw',sensible:r.shr*100},T('Quy đổi tải thiết kế sang lưu lượng','Convert design load to flow'));}}
if(kind==='duct'){const x=getInput(),r=rows[selected??0]||rows[0];if(r&&document.getElementById('error').hidden){target.innerHTML=a(['chon-quat','fan-sizing'],{flow:x.q*3600,a:r.a,b:r.b,shape:shape,length:x.l,rough:x.e,rho:101325/(287.05*(x.t+273.15)),mu:1.716e-5*((x.t+273.15)/273.15)**1.5*(273.15+110.4)/(x.t+273.15+110.4)*1e6},T('Tính áp suất chọn quạt','Calculate fan pressure'))+a(['mieng-gio','grille-sizing'],{flow:x.q*3600},T('Chọn miệng gió','Size grilles'))+(document.getElementById('material').selectedIndex===2?'':a(['che-tao-ong-gio','duct-fabrication'],{insideA:r.a,insideB:r.b,shape,length:x.l},T('Quy cách chế tạo & vật tư','Fabrication & take-off'))+a(['gia-do-ong-gio','duct-supports'],{insideA:r.a,insideB:r.b,shape},T('Tính giá đỡ & ty treo','Check supports & rods')));}}
if(kind==='water'){const x=waterInput();if(waterChosen&&!x.gravity&&W('error').hidden){target.innerHTML=a(['chon-bom','pump-sizing'],{flow:x.q*3600,d:waterChosen.diameter,length:x.l,temp:x.t,rough:x.e,system:W('system').value==='chiller'?'closed':'open'},T('Tính cột áp chọn bơm','Calculate pump head'));}}section.hidden=!target.innerHTML;}
document.addEventListener('input',refresh);document.addEventListener('change',refresh);document.addEventListener('click',refresh);refresh();})();
